MOD = 10**9 + 7

def count_similar_permutations(n, a):
    # Initialize the dp array
    dp = [0] * (n + 1)
    dp[0] = 1  # There is one way to have an empty permutation

    for mex in range(n):
        new_dp = [0] * (n + 1)
        for r in range(n):
            if a[r] == mex:
                for l in range(r + 1):
                    if all(a[i] != mex for i in range(l, r + 1)):
                        new_dp[r + 1] = (new_dp[r + 1] + dp[l]) % MOD
        dp = new_dp

    return dp[n]

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        results.append(count_similar_permutations(n, a))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
